import{_ as e,a as d,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Get Cart","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-cart","title":"Get Cart","description":"Read the current cart with its items and recalculated totals. The cart is identified by the token sent in the Authorization header.","request":"curl -X POST \\"http://localhost/api/shop/cart\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\" \\\\\\n  -H \\"Authorization: Bearer 62f2b3f5-a455-4c78-93ba-eabca63d32ec\\" \\\\\\n  -d \'{}\'\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 495,\\n  \\"cartToken\\": \\"62f2b3f5-a455-4c78-93ba-eabca63d32ec\\",\\n  \\"customerId\\": null,\\n  \\"channelId\\": 1,\\n  \\"itemsCount\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"id\\": 358,\\n      \\"cartId\\": 495,\\n      \\"productId\\": 2,\\n      \\"name\\": \\"Blossom Breeze Cotton Printed Short Skirt\\",\\n      \\"sku\\": \\"ws-blossom-skirt\\",\\n      \\"quantity\\": 1,\\n      \\"price\\": 24.99,\\n      \\"basePrice\\": 24.99,\\n      \\"total\\": 24.99,\\n      \\"baseTotal\\": 24.99,\\n      \\"discountAmount\\": 0,\\n      \\"baseDiscountAmount\\": 0,\\n      \\"taxAmount\\": 0,\\n      \\"baseTaxAmount\\": 0,\\n      \\"options\\": null,\\n      \\"type\\": \\"simple\\",\\n      \\"formattedPrice\\": \\"$24.99\\",\\n      \\"formattedTotal\\": \\"$24.99\\",\\n      \\"priceInclTax\\": 24.99,\\n      \\"formattedPriceInclTax\\": \\"$24.99\\",\\n      \\"totalInclTax\\": 24.99,\\n      \\"formattedTotalInclTax\\": \\"$24.99\\",\\n      \\"productUrlKey\\": \\"blossom-breeze-cotton-printed-short-skirt\\",\\n      \\"canChangeQty\\": true\\n    }\\n  ],\\n  \\"subtotal\\": 24.99,\\n  \\"baseSubtotal\\": 24.99,\\n  \\"discountAmount\\": 0,\\n  \\"taxAmount\\": 0,\\n  \\"shippingAmount\\": 0,\\n  \\"grandTotal\\": 24.99,\\n  \\"formattedSubtotal\\": \\"$24.99\\",\\n  \\"formattedDiscountAmount\\": \\"$0.00\\",\\n  \\"formattedTaxAmount\\": \\"$0.00\\",\\n  \\"formattedShippingAmount\\": \\"$0.00\\",\\n  \\"formattedGrandTotal\\": \\"$24.99\\",\\n  \\"couponCode\\": null,\\n  \\"isGuest\\": true\\n}\\n","commonErrors":[{"error":"404 Not Found","cause":"No cart exists for the supplied token, or the cart is empty and was cleared","solution":"Create a cart and add an item before reading it."},{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/get-cart.md","filePath":"api/rest-api/shop/cart/get-cart.md","lastUpdated":1787725411000}'),r={name:"api/rest-api/shop/cart/get-cart.md"};function n(i,t,s,c,l,h){return a(),d("div",null,t[0]||(t[0]=[o('<h1 id="get-cart" tabindex="-1">Get Cart <a class="header-anchor" href="#get-cart" aria-label="Permalink to &quot;Get Cart&quot;">​</a></h1><p>Read the current cart with its line items and recalculated totals.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/cart</span></span></code></pre></div><p>Reading the cart is a <strong>POST</strong>, not a GET. The cart is identified by the token in the <code>Authorization</code> header rather than by a path parameter, and the endpoint takes an empty JSON body.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>Accept</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td><code>Bearer &lt;cartToken&gt;</code> for a guest, or the customer&#39;s Bearer token when signed in</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{}</span></span></code></pre></div><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><p>The response is the cart itself, returned as a bare object with no wrapper.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Cart ID.</td></tr><tr><td><code>cartToken</code></td><td>string</td><td>Token identifying this cart.</td></tr><tr><td><code>customerId</code></td><td>integer</td><td>Owning customer, or <code>null</code> for a guest cart.</td></tr><tr><td><code>channelId</code></td><td>integer</td><td>Channel the cart belongs to.</td></tr><tr><td><code>itemsCount</code></td><td>integer</td><td>Number of line items.</td></tr><tr><td><code>itemsQty</code></td><td>integer</td><td>Total units across those lines.</td></tr><tr><td><code>items</code></td><td>array</td><td>Line items — fields below.</td></tr><tr><td><code>subtotal</code> / <code>baseSubtotal</code></td><td>decimal</td><td>Items subtotal.</td></tr><tr><td><code>discountAmount</code> / <code>baseDiscountAmount</code></td><td>decimal</td><td>Discount applied.</td></tr><tr><td><code>taxAmount</code> / <code>baseTaxAmount</code></td><td>decimal</td><td>Tax calculated.</td></tr><tr><td><code>shippingAmount</code> / <code>baseShippingAmount</code></td><td>decimal</td><td>Shipping cost, once a method is chosen.</td></tr><tr><td><code>grandTotal</code> / <code>baseGrandTotal</code></td><td>decimal</td><td>Grand total.</td></tr><tr><td><code>formattedSubtotal</code>, <code>formattedDiscountAmount</code>, <code>formattedTaxAmount</code>, <code>formattedShippingAmount</code>, <code>formattedGrandTotal</code></td><td>string</td><td>The same amounts, currency-formatted.</td></tr><tr><td><code>couponCode</code></td><td>string</td><td>Applied coupon, or <code>null</code>.</td></tr><tr><td><code>isGuest</code></td><td>boolean</td><td>Whether the cart belongs to a guest.</td></tr></tbody></table><h3 id="item-fields" tabindex="-1">Item Fields <a class="header-anchor" href="#item-fields" aria-label="Permalink to &quot;Item Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Cart item ID. <strong>This is what the update and remove endpoints expect.</strong></td></tr><tr><td><code>cartId</code></td><td>integer</td><td>Parent cart ID.</td></tr><tr><td><code>productId</code></td><td>integer</td><td>Product on this line.</td></tr><tr><td><code>name</code> / <code>sku</code></td><td>string</td><td>Product name and SKU as added.</td></tr><tr><td><code>quantity</code></td><td>integer</td><td>Units on this line.</td></tr><tr><td><code>price</code> / <code>total</code></td><td>decimal</td><td>Unit price and line total.</td></tr><tr><td><code>formattedPrice</code> / <code>formattedTotal</code></td><td>string</td><td>The same values, currency-formatted.</td></tr><tr><td><code>priceInclTax</code> / <code>totalInclTax</code></td><td>decimal</td><td>Tax-inclusive equivalents, with <code>formatted*</code> variants.</td></tr><tr><td><code>discountAmount</code> / <code>taxAmount</code></td><td>decimal</td><td>Per-line discount and tax.</td></tr><tr><td><code>options</code></td><td>array</td><td>Selected options for configurable, bundle, and customizable products. <code>null</code> when none apply.</td></tr><tr><td><code>type</code></td><td>string</td><td>Product type of the line.</td></tr><tr><td><code>baseImage</code></td><td>string</td><td>JSON string of the product&#39;s image URLs at each size.</td></tr><tr><td><code>productUrlKey</code></td><td>string</td><td>Storefront slug, for linking back to the product.</td></tr><tr><td><code>canChangeQty</code></td><td>boolean</td><td><code>false</code> for event and appointment bookings, whose quantity is fixed.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Render the cart page</strong> — one call returns items and every total needed for the summary panel.</li><li><strong>Refresh the mini-cart</strong> — read after any change to pick up recalculated totals.</li><li><strong>Resume a guest session</strong> — a stored <code>cartToken</code> restores the cart on a return visit.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Treat <code>404 Cart not found</code> as &quot;no cart yet&quot;</strong> — a cart only exists once an item has been added, and it is cleared again when the last item is removed</li><li><strong>Read the totals from the response, not from your own arithmetic</strong> — discounts and tax are recalculated server-side on every change</li><li><strong>Use the <code>formatted*</code> fields for display</strong> — they carry the active currency&#39;s symbol and formatting</li><li><strong>Keep the numeric item <code>id</code></strong> — update and remove both key off it</li></ol><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/create-cart.html">Create Cart</a> — obtain the cart token every other cart call needs</li><li><a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a> — add a product of any type to the cart</li><li><a href="/api/rest-api/shop/cart/update-cart-item.html">Update Cart Item</a> — change a line&#39;s quantity</li><li><a href="/api/rest-api/shop/cart/remove-cart-item.html">Remove Cart Item</a> — remove one line, or several in one call</li></ul>',20)]))}const m=e(r,[["render",n]]);export{p as __pageData,m as default};
